contract InvMutTest {
    C c;
    address payable ownerAddr;
    constructor(C _c) { c = _c; ownerAddr = payable(address(this)); }

    // Try withdrawing either as owner (this contract) or simulate non-owner by calling from c via sendMoney
    // We take two parameters: amount to deposit via fallback, and withdrawAmount to attempt to withdraw.
    function run(uint depositAmount, uint withdrawAmount, address payable victim) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
        // Deposit Ether into c by calling its fallback via a direct call with value
        // Use low-level call to trigger fallback: calling a function on c with value would work too, but spec says use public/external surface only.
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // Record balances before withdraw attempts
        uint cBalanceBefore = address(c).balance;
        uint testerBalanceBefore = address(this).balance;

        // First, attempt to withdraw as owner (this contract is the owner because InvMutTest deployed c)
        bool ownerReverted;
        try c.withdraw(withdrawAmount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        uint cBalanceAfterOwner = address(c).balance;
        uint testerBalanceAfterOwner = address(this).balance;

        // Now attempt to withdraw as a non-owner by asking c to call sendMoney to transfer to victim from c's balance.
        // sendMoney requires onlyOwner, so it should revert when called since msg.sender (this contract) is owner;
        // to simulate a non-owner withdraw attempt we instead have c send to victim (this still runs as onlyOwner and should succeed),
        // but we can test that external transfers only happen when called by owner by trying a direct low-level call from this contract
        // to c.withdraw: that still originates from this contract (owner) so to create a non-owner call we perform a call with a different msg.sender is impossible here.
        // Instead we check the invariant: if a withdraw did not revert for owner then c's balance decreased by at most withdrawAmount and this contract's balance increased by at most withdrawAmount.

        // Compute deltas
        uint cDeltaOwner = cBalanceBefore >= cBalanceAfterOwner ? cBalanceBefore - cBalanceAfterOwner : 0;
        uint testerDeltaOwner = testerBalanceAfterOwner >= testerBalanceBefore ? testerBalanceAfterOwner - testerBalanceBefore : 0;

        // The general rule asserted:
        // If owner withdraw did NOT revert, then c's balance decreased by exactly the amount transferred out and the tester's balance increased by the same amount, up to the requested withdrawAmount (withdraw transfers _value or contract throws); if it reverted then balances unchanged.
        assert(
            ownerReverted
            ? (cBalanceAfterOwner == cBalanceBefore && testerBalanceAfterOwner == testerBalanceBefore)
            : (cDeltaOwner == testerDeltaOwner && cDeltaOwner <= withdrawAmount && testerDeltaOwner <= withdrawAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmount to send into c (to fund), withdrawAmount to request withdrawing
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // Deposit Ether into c by triggering its fallback via a plain low-level call
        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        // observe balances before withdraw
        uint cBalanceBefore = address(c).balance;
        uint testerBalanceBefore = address(this).balance;

        // attempt withdraw as owner (this contract is owner because it deployed c)
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // observe balances after withdraw
        uint cBalanceAfter = address(c).balance;
        uint testerBalanceAfter = address(this).balance;

        // compute observed deltas safely (no underflow in assert)
        uint cDelta = cBalanceBefore >= cBalanceAfter ? cBalanceBefore - cBalanceAfter : 0;
        uint testerDelta = testerBalanceAfter >= testerBalanceBefore ? testerBalanceAfter - testerBalanceBefore : 0;

        // General property:
        // - If withdraw reverted: balances unchanged.
        // - If withdraw succeeded: the decrease in C's balance equals the increase in tester's balance,
        //   and that amount is <= withdrawAmount.
        assert(
            withdrewReverted
            ? (cBalanceAfter == cBalanceBefore && testerBalanceAfter == testerBalanceBefore)
            : (cDelta == testerDelta && cDelta <= withdrawAmount)
        );
    }

    receive() external payable {}
}

