        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        // observe balances before withdrawAll
        uint cBalanceBefore = address(c).balance;
        uint testerBalanceBefore = address(this).balance;

        // attempt withdrawAll as owner (this contract deployed c so it's owner)
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // observe balances after withdrawAll
        uint cBalanceAfter = address(c).balance;
        uint testerBalanceAfter = address(this).balance;

        // General property:
        // - If withdrawAll reverted: balances unchanged.
        // - If withdrawAll succeeded: all Ether that was in C before is transferred to tester (owner).
        assert(
            withdrewReverted
            ? (cBalanceAfter == cBalanceBefore && testerBalanceAfter == testerBalanceBefore)
            : (cBalanceBefore >= cBalanceAfter && // c's balance does not increase
               cBalanceAfter == 0 && // all funds were removed from C
               testerBalanceAfter >= testerBalanceBefore && // tester's balance does not decrease
               testerBalanceAfter - testerBalanceBefore == cBalanceBefore) // tester gained exactly what C had
        );
    }

    receive() external payable {}
}

