contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll test that withdraw by a non-owner reverts and does not change contract balance or depositsCount.
    // Parameters:
    // - senderIsOwner: if true, call withdraw from this contract (owner) — allowed; otherwise simulate a non-owner by using a forwarded call from an externally controlled address cannot be done here, so instead we use sendMoney to attempt to transfer funds out to a non-owner target and ensure onlyOwner prevents withdraw; to create a non-owner call we rely on calling c.withdraw via a try/catch where msg.sender is this contract (the owner) vs expecting revert when calling withdraw via a low-level call with a different caller is not possible in this environment. To produce a meaningful universal assertion we instead assert that withdraw never increases address(c).balance and that onlyOwner protects against arbitrary value changes: calling withdraw with any _value cannot increase c balance and withdrawals larger than balance still succeed only for owner.
    // To satisfy constraints, we take amount to deposit into c via fallback and then attempt withdraw of any value; ensure owner (this) can withdraw up to balance, and that after withdrawAll the balance is zero.

    // Note: we must not rely on external addresses changing caller identity; the main universal property we assert:
    // After depositing 'deposit' wei into c (via fallback), if this contract calls withdrawAll then address(c).balance == 0 and address(this).balance increased by same amount.

    function run(uint deposit, uint withdrawAmount) public payable {
        require(address(this).balance >= deposit, "insufficient balance to fund deposit");
        // initial observations
        uint beforeCBalance = address(c).balance;
        uint beforeDepositsCount = c.depositsCount();
        uint beforeThisBalance = address(this).balance;

        // Make a deposit by sending Ether to c's fallback (which increments depositsCount)
        c.f{value: deposit}();

        // Read after deposit
        uint midCBalance = address(c).balance;
        uint midDepositsCount = c.depositsCount();

        // Now as owner (this contract is owner) call withdraw with withdrawAmount (may be > balance)
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Finally call withdrawAll (should succeed only for owner) and observe balances
        // Use try/catch to ensure function reachable even if revert occurs earlier
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        uint afterDepositsCount = c.depositsCount();

        // General rule asserted:
        // 1) The deposit increased c balance by exactly deposit and increased depositsCount by 1.
        // 2) After withdrawAll (called by owner), either withdrawAll reverted or it drained the contract: if it did not revert then c.balance == 0 and this contract's balance increased by (midCBalance - afterCBalance).
        // Combine into single assert formula below.
        assert(
            // deposit observation: c balance increased by deposit and depositsCount incremented by 1
            midCBalance == beforeCBalance + deposit && midDepositsCount == beforeDepositsCount + 1
            &&
            // If withdrawAll did not revert then c.balance is zero and this contract gained exactly the drained amount
            ((withdrewAllReverted == true) || (afterCBalance == 0 && afterThisBalance == beforeThisBalance + (midCBalance - afterCBalance)))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a deposit amount and a withdrawAttempt amount (unused except to trigger withdraw try/catch).
    // The test: deposit via low-level call to trigger fallback(), observe balance and depositsCount change by +amount and +1;
    // then as owner call withdrawAll and assert that if withdrawAll did not revert then c balance is zero and this contract gained the drained funds.
    function run(uint deposit, uint /*withdrawAttempt*/) public payable {
        require(address(this).balance >= deposit, "insufficient balance to fund deposit");

        // observe before
        uint beforeCBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        uint beforeThis = address(this).balance;

        // Deposit to c by sending ETH to its fallback via low-level call
        (bool ok, ) = address(c).call{value: deposit}("");
        require(ok, "deposit call failed");

        // observations after deposit
        uint midCBalance = address(c).balance;
        uint midDeposits = c.depositsCount();

        // Owner (this contract) attempts withdrawAll; capture revert
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        uint afterCBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule asserted in single assert:
        // 1) The deposit increased c balance by exactly deposit and depositsCount by exactly 1.
        // 2) If withdrawAll did not revert then c balance is zero and this contract gained exactly the drained amount.
        assert(
            midCBalance == beforeCBalance + deposit
            && midDeposits == beforeDeposits + 1
            && (
                withdrewAllReverted == true
                || (afterCBalance == 0 && afterThis == beforeThis + (midCBalance - afterCBalance))
            )
        );
    }

    receive() external payable {}
}

