contract InvMutTest {
    C c;
    address payable ownerAddr;

    constructor(C _c) {
        c = _c;
        ownerAddr = payable(address(this));
    }

    // We implement receive so that c.sendMoney or c.withdraw can transfer Ether back to this contract
    receive() external payable {}

    // params: whichAction: 0 = send money via fallback to c, 1 = withdraw value, 2 = withdrawAll, 3 = sendMoney to target
    // amount: amount of wei to send to or withdraw from c. target: address to forward to when testing sendMoney.
    function run(uint8 whichAction, uint amount, address payable target) public payable {
        require(whichAction <= 3);
        // Ensure this test contract has enough funds if we will send ether into c
        if (whichAction == 0) {
            require(address(this).balance >= amount);
            // send ETH to c via low-level call to trigger fallback which increments depositsCount
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok);
            // After sending, address(c).balance should have increased by amount and depositsCount incremented by 1
            uint b = address(c).balance;
            uint d = c.depositsCount();
            // general rule: depositsCount increased by at least 1 and contract balance reflects the sent amount >= amount
            // Because we can't read prior values easily, assert that depositsCount is >=1 and balance >= amount
            assert(d >= 1 && b >= amount);
        } else if (whichAction == 1) {
            // withdraw a specific amount as owner (this contract is the owner). First ensure c has enough balance by funding it.
            // Fund c with amount via call
            if (amount > 0) {
                require(address(this).balance >= amount);
                (bool okf, ) = address(c).call{value: amount}("");
                require(okf);
            }
            uint before = address(this).balance;
            uint cbefore = address(c).balance;
            // call withdraw as owner; must not revert
            bool reverted;
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint after = address(this).balance;
            uint cafter = address(c).balance;
            // General invariant: since this contract is owner, withdraw should not revert and balances must reflect transfer when not reverted
            assert(reverted == false && after == before + (cbefore - cafter) && (cbefore - cafter) <= cbefore);
        } else if (whichAction == 2) {
            // withdrawAll as owner: ensure c has some balance first
            if (amount > 0) {
                require(address(this).balance >= amount);
                (bool okf, ) = address(c).call{value: amount}("");
                require(okf);
            }
            uint before = address(this).balance;
            uint cbefore = address(c).balance;
            bool reverted;
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint after = address(this).balance;
            uint cafter = address(c).balance;
            // As owner, withdrawAll should not revert and should transfer all remaining balance to owner
            assert(reverted == false && cafter == 0 && after == before + cbefore);
        } else {
            // whichAction == 3: test sendMoney to target
            // Ensure c has at least amount by funding it if needed
            if (amount > 0) {
                require(address(this).balance >= amount);
                (bool okf, ) = address(c).call{value: amount}("");
                require(okf);
            }
            uint tbefore = target.balance;
            uint cbefore = address(c).balance;
            bool reverted;
            try c.sendMoney(target, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint tafter = target.balance;
            uint cafter = address(c).balance;
            // As owner, sendMoney must not revert and transfer amount to target (assuming target accepts ETH)
            // We assert that if not reverted then target balance increased by amount and c balance decreased by amount
            assert(reverted == false && tafter == tbefore + amount && cafter == cbefore - amount);
        }
    }
}

contract InvMutTest {
    C c;
    address payable ownerAddr;

    constructor(C _c) {
        c = _c;
        ownerAddr = payable(address(this));
    }

    receive() external payable {}

    // whichAction: 1 = withdraw(amount), 2 = withdrawAll(), 3 = sendMoney(target, amount)
    function run(uint8 whichAction, uint amount, address payable target) public payable {
        require(whichAction >= 1 && whichAction <= 3);

        // If we will need c to have funds, fund it from this contract first
        if (whichAction == 1 || whichAction == 2 || whichAction == 3) {
            // Fund c with `amount` if amount>0 to ensure sufficient balance for transfers
            if (amount > 0) {
                require(address(this).balance >= amount);
                (bool fok, ) = address(c).call{value: amount}("");
                require(fok);
            }
        }

        if (whichAction == 1) {
            // Test withdraw(amount)
            uint beforeOwner = address(this).balance;
            uint beforeC = address(c).balance;
            bool reverted;
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint afterOwner = address(this).balance;
            uint afterC = address(c).balance;

            // If call did not revert then owner balance must increase by exactly the amount withdrawn
            // and contract balance must decrease by the same amount. The withdrawn amount cannot exceed beforeC.
            assert(reverted == false && afterOwner == beforeOwner + (beforeC - afterC) && (beforeC - afterC) <= beforeC);
        } else if (whichAction == 2) {
            // Test withdrawAll()
            uint beforeOwner = address(this).balance;
            uint beforeC = address(c).balance;
            bool reverted;
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint afterOwner = address(this).balance;
            uint afterC = address(c).balance;

            // If not reverted then contract should be drained and owner balance increased by the drained amount
            assert(reverted == false && afterC == 0 && afterOwner == beforeOwner + beforeC);
        } else {
            // whichAction == 3: sendMoney(target, amount)
            // Ensure target is not this contract to avoid ambiguity in received funds accounting
            require(target != address(this));

            uint beforeTarget = target.balance;
            uint beforeC = address(c).balance;
            bool reverted;
            try c.sendMoney(target, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint afterTarget = target.balance;
            uint afterC = address(c).balance;

            // If not reverted then target must have received `amount` and c balance reduced by `amount`.
            // Note: if beforeC < amount the call would revert; since we funded with `amount` when amount>0 above,
            // this ensures beforeC >= amount, so non-revert implies exact transfer.
            assert(reverted == false && afterTarget == beforeTarget + amount && afterC == beforeC - amount);
        }
    }
}

contract InvMutTest {
    C c;
