    receive() external payable {}

    // whichAction: 1 = withdraw(amount) to this contract (owner), 2 = withdrawAll(), 3 = sendMoney(target, amount)
    function run(uint8 whichAction, uint amount, address payable target) public payable {
        require(whichAction >= 1 && whichAction <= 3);

        // Fund c if needed to allow non-reverting transfers when amount>0
        if (amount > 0) {
            require(address(this).balance >= amount);
            bool okFund;
            (okFund, ) = address(c).call{value: amount}("");
            require(okFund);
        }

        // Read before-values
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeTarget = target.balance;

        bool didRevert;

        if (whichAction == 1) {
            // withdraw(amount)
            didRevert = false;
            try c.withdraw(amount) {
            } catch {
                didRevert = true;
            }
        } else if (whichAction == 2) {
            // withdrawAll()
            didRevert = false;
            try c.withdrawAll() {
            } catch {
                didRevert = true;
            }
        } else {
            // sendMoney(target, amount)
            didRevert = false;
            try c.sendMoney(target, amount) {
            } catch {
                didRevert = true;
            }
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterTarget = target.balance;

        // Single general assert covering all actions:
